<script setup lang="ts">
import { reactive, watch } from 'vue';
import { NAlert, NButton, NForm, NFormItem, NInput, NTag } from 'naive-ui';
import type { AppSettings, Health } from '../types.ts';
import AppIcon from '../components/AppIcon.vue';
const props = defineProps<{ settings: AppSettings; health: Health | null; disabled: boolean; saving: boolean; checking: boolean }>();
const emit = defineEmits<{ save: [input: AppSettings]; check: [] }>();
const form = reactive({ ...props.settings });
watch(() => props.settings, settings => { Object.assign(form, settings); });
function submit() { if (form.ffmpegPath.trim() && form.ffprobePath.trim()) emit('save', { ffmpegPath: form.ffmpegPath.trim(), ffprobePath: form.ffprobePath.trim() }); }
</script>

<template>
  <div class="settings-view readable-view"><header class="page-heading"><div><p class="eyebrow">YOUR LOCAL STUDIO</p><h1>工作台设置</h1><p class="subheading">检查本地工具，让导入与导出顺畅运行。</p></div><NButton :loading="checking" :disabled="disabled" @click="emit('check')"><template #icon><AppIcon name="refresh" :size="16" /></template>重新检测</NButton></header><div class="settings-layout"><section class="panel settings-card"><div class="panel-heading"><h2>媒体工具</h2><NTag :bordered="false" :type="health?.status === 'ok' ? 'success' : 'warning'">{{ health?.status === 'ok' ? '工具就绪' : '需要检查' }}</NTag></div><p class="settings-description">使用已安装的 FFmpeg 和 ffprobe。可以填写命令名称，或可执行文件的完整路径。</p><NForm @submit.prevent="submit"><NFormItem label="FFmpeg 可执行文件" label-for="ffmpeg-path"><NInput id="ffmpeg-path" v-model:value="form.ffmpegPath" placeholder="ffmpeg" :disabled="disabled" /></NFormItem><NFormItem label="ffprobe 可执行文件" label-for="ffprobe-path"><NInput id="ffprobe-path" v-model:value="form.ffprobePath" placeholder="ffprobe" :disabled="disabled" /></NFormItem><NButton type="primary" attr-type="submit" :loading="saving" :disabled="disabled || !form.ffmpegPath.trim() || !form.ffprobePath.trim()">保存并检测</NButton></NForm><div v-if="health" class="tool-results"><article v-for="tool in [{ name: 'FFmpeg', value: health.ffmpeg }, { name: 'ffprobe', value: health.ffprobe }]" :key="tool.name" class="tool-result"><div class="heading-line"><span class="status-dot" :class="{ unavailable: !tool.value.available }"></span><strong>{{ tool.name }}</strong><span class="muted small">{{ tool.value.available ? '可用' : '不可用' }}</span></div><code>{{ tool.value.path }}</code><p v-if="tool.value.version" class="small muted">{{ tool.value.version }}</p><NAlert v-if="tool.value.error" type="error" :show-icon="false">{{ tool.value.error }}</NAlert></article></div></section><section class="panel settings-card storage-card"><div class="panel-heading"><h2>本机工作区</h2><AppIcon name="projects" :size="20" /></div><p class="settings-description">素材复制到项目受管目录，项目与任务记录存储在本地。</p><dl v-if="health" class="detail-list"><div><dt>应用版本</dt><dd>{{ health.version }}</dd></div><div><dt>数据结构版本</dt><dd>{{ health.schemaVersion }}</dd></div><div><dt>应用数据</dt><dd><code>{{ health.dataDir }}</code></dd></div><div><dt>项目目录</dt><dd><code>{{ health.projectsDir }}</code></dd></div></dl><p class="panel-footnote">备份与恢复步骤见仓库文档。需要切换数据目录时，请先停止服务并通过启动配置设置。</p><div class="local-note"><span class="status-dot"></span><p>你的素材与成片<br /><strong>由你自己保管。</strong></p></div></section></div></div>
</template>
